import { createAsyncThunk, createSlice } from '@reduxjs/toolkit'

type User = { id: string; name: string }

type State = { user?: User; status: string; currentRequestId?: string; error?: string }
const initialState: State = { status: 'idle' }

export const fetchUser = createAsyncThunk<User, string>(
  'users/fetchUser',
  async id => (await fetch(`/api/users/${id}`)).json()
)

const users = createSlice({
  name: 'users', initialState,
  reducers: {},
  extraReducers: builder => builder
    .addCase(fetchUser.pending, (state, action) => {
      state.status = 'pending'
      state.currentRequestId = action.meta.requestId
    })
    .addCase(fetchUser.fulfilled, (state, action) => {
      if (state.currentRequestId !== action.meta.requestId) return
      state.status = 'fulfilled'; state.user = action.payload
    })
    .addCase(fetchUser.rejected, (state, action) => {
      if (state.currentRequestId !== action.meta.requestId) return
      state.status = 'rejected'; state.error = action.error.message
    })
})

export default users.reducer

